# Generates the reference fixture read by `faer/tests/ql_rq.rs` (colmat-rs#60).
# Run once, offline, and check the output in:
#
#     julia --startup-file=no --project=<env> faer/tests/fixtures/ql_rq_reference/generate.jl
#
# where <env> has MatrixFactorizations.jl at the reference commit of the issue:
#
#     Pkg.add(url="https://github.com/JuliaLinearAlgebra/MatrixFactorizations.jl",
#             rev="a38f07fbbcb8abebb203bf67fc745b8c262d6d19")
#
# MatrixFactorizations.jl is MIT, Copyright (c) 2019 JuliaLinearAlgebra. Only its
# output is used here, as the test oracle.
#
# For each case the fixture holds A (17 significant digits, exact round trip), the
# thin Q and the compact triangular factor, both in the positive diagonal gauge:
#
# - QL, A = Q L: Q is m x k (the last k columns of the full Q; `Matrix(F.Q)` would
#   give the first k, which do not reproduce A when m > n), L is k x n, and the
#   diagonal that ends in the last row and column, L[r, r + n - k], is real and
#   nonnegative.
# - RQ, A = R Q: R is m x k, Q is k x n (the last k rows of the full Q), and the
#   diagonal R[r + m - k, r] is real and nonnegative.
#
# MatrixFactorizations.jl does not fix that gauge, so this script applies it: a
# full-rank factorization is unique once it is fixed, and the test compares
# entry by entry. A complex matrix is written as its real and imaginary parts.
using MatrixFactorizations, LinearAlgebra, Printf, Random

const OUT = joinpath(@__DIR__, "ql_rq.txt")

fmt(x::Float64) = @sprintf("%.17g", x)
function writemat(io, name, M)
    parts = eltype(M) <: Complex ? [("_re", real.(M)), ("_im", imag.(M))] : [("", M)]
    for (suffix, P) in parts
        println(io, name, suffix, " ", size(P, 1), " ", size(P, 2))
        for i in 1:size(P, 1)
            println(io, join(fmt.(P[i, :]), " "))
        end
    end
end
phase(d) = iszero(d) ? one(d) : d / abs(d)

function ql_case(A)
    m, n = size(A)
    k = min(m, n)
    F = ql(A)
    Q = (F.Q * Matrix{eltype(A)}(I, m, m))[:, m-k+1:m]
    L = Matrix(F.L)
    for r in 1:k
        p = phase(L[r, r+n-k])
        L[r, :] .*= conj(p)
        Q[:, r] .*= p
    end
    @assert norm(Q * L - A) <= 1e-13 * norm(A)
    Q, L
end

function rq_case(A)
    m, n = size(A)
    k = min(m, n)
    G = rq(A)
    Q = (G.Q * Matrix{eltype(A)}(I, n, n))[n-k+1:n, :]
    R = Matrix(G.R)
    for r in 1:k
        p = phase(R[r+m-k, r])
        R[:, r] .*= conj(p)
        Q[r, :] .*= p
    end
    @assert norm(R * Q - A) <= 1e-13 * norm(A)
    R, Q
end

open(OUT, "w") do io
    println(io, "# generated by faer/tests/fixtures/ql_rq_reference/generate.jl")
    println(io, "# julia ", VERSION, ", MatrixFactorizations.jl ",
        pkgversion(MatrixFactorizations), " at a38f07fbbcb8abebb203bf67fc745b8c262d6d19")
    rng = MersenneTwister(60)
    for T in (Float64, ComplexF64), (m, n) in ((5, 3), (3, 5), (4, 4))
        A = randn(rng, T, m, n)
        dtype = T == Float64 ? "f64" : "c64"
        Q, L = ql_case(A)
        println(io, "case ql ", dtype, " ", m, " ", n)
        writemat(io, "a", A)
        writemat(io, "q", Q)
        writemat(io, "t", L)
        R, Qr = rq_case(A)
        println(io, "case rq ", dtype, " ", m, " ", n)
        writemat(io, "a", A)
        writemat(io, "q", Qr)
        writemat(io, "t", R)
    end
end
